  1→/**
  2→ * DeterministicProfileEngine.js
  3→ *
  4→ * PURE FUNCTIONS for cognitive profile computation.
  5→ *
  6→ * CRITICAL INVARIANT: Same answers → Same profile. Always.
  7→ * NO Math.random(). NO Date.now() in computation. NO side effects.
  8→ *
  9→ * This engine defeats non-determinism in profile generation by:
 10→ * 1. Fixed reduction order (answers processed in dimension order)
 11→ * 2. Pure functions (no external state)
 12→ * 3. Checksum verification (integrity across transmission)
 13→ *
 14→ * Based on insights from "Defeating Non-Determinism in LLM Inference"
 15→ * https://thinkingmachines.ai/blog/defeating-nondeterminism-in-llm-inference/
 16→ */
 17→
 18→import { VERSION, getGeneratorString } from '../config/version.js';
 19→
 20→/**
 21→ * Dimension configuration — the semantic schema
 22→ * Order matters for determinism: processed alphabetically
 23→ */
 24→const DIMENSION_CONFIG = {
 25→  ambiguity: {
 26→    high: { label: 'Comfortable', behavior: 'You handle uncertainty well — explore possibilities' },
 27→    mid: { label: 'Balanced', behavior: 'You appreciate both clarity and exploration' },
 28→    low: { label: 'Wants Clarity', behavior: 'You prefer clear answers — be direct about unknowns' }
 29→  },
