 32→    mid: { label: 'Contextual', behavior: 'Match feedback style to the situation' },
 33→    low: { label: 'Direct', behavior: 'Tell it straight — you can handle direct feedback' }
 34→  },
 35→  exploration: {
 36→    high: { label: 'Expansive', behavior: 'You enjoy exploring tangents and connections' },
 37→    mid: { label: 'Selective', behavior: 'Follow interesting threads, redirect boring ones' },
 38→    low: { label: 'Focused', behavior: 'Stay on track — goal-directed conversations' }
 39→  },
