277→|-----------|------------|-------|----------|
278→`;
279→
280→    const sortedDims = Object.keys(profile.traits).sort();
281→    sortedDims.forEach(dim => {
282→      const trait = profile.traits[dim];
283→      const dimTitle = dim.charAt(0).toUpperCase() + dim.slice(1);
284→      md += `| ${dimTitle} | ${trait.label} | ${trait.value.toFixed(2)} | ${trait.behavior} |\n`;
285→    });
286→
287→    md += `
288→## Key Insights
289→
290→`;
291→    profile.insights.forEach((insight, i) => {
292→      md += `${i + 1}. ${insight}\n`;
293→    });
294→
295→    md += `
296→## Integrity
