318→  /**
319→   * Generate CLAUDE.md integration snippet
320→   * Ready to paste into the Cognitive Substrate section
321→   */
322→  static toClaudeIntegration(profile) {
323→    return `
324→<!-- TRANSLATORS PROFILE INTEGRATION -->
