225→void UBridgeComponent::ProcessStateFile()
226→{
227→    // Try USD mode first (v2.0.0)
228→    FString UsdFilePath = GetBridgeFilePath(TEXT("bridge_state.usda"));
229→    IPlatformFile& PlatformFile = FPlatformFileManager::Get().GetPlatformFile();
230→
231→    if (PlatformFile.FileExists(*UsdFilePath))
232→    {
233→        if (ProcessBridgeStateUsda())
234→        {
235→            return; // Successfully processed USD
236→        }
237→    }
238→
239→    // Fall back to JSON mode (v1.0.0)
240→    FString FilePath = GetBridgeFilePath(TEXT("state.json"));
241→    FString Content;
242→
243→    BridgeLog(FString::Printf(TEXT("Attempting to read: %s"), *FilePath));
244→
245→    if (!FFileHelper::LoadFileToString(Content, *FilePath))
246→    {
247→        BridgeLog(FString::Printf(TEXT("FAILED to read: %s (exists: %d)"),
248→            *FilePath, PlatformFile.FileExists(*FilePath) ? 1 : 0));
249→        return;
250→    }
251→
252→    // Parse JSON
253→    TSharedPtr<FJsonObject> JsonObj;
254→    TSharedRef<TJsonReader<>> Reader = TJsonReaderFactory<>::Create(Content);
255→
256→    if (!FJsonSerializer::Deserialize(Reader, JsonObj) || !JsonObj.IsValid())
257→    {
258→        BridgeLog(TEXT("ERROR: Invalid JSON in state.json"));
259→        return;
260→    }
261→
262→    CurrentStateJson = Content;
263→    bUsingUsdMode = false;
264→
265→    // Route by type
266→    FString StateType;
267→    if (JsonObj->TryGetStringField(TEXT("type"), StateType))
268→    {
269→        if (StateType == TEXT("ready"))
270→        {
271→            HandleReadyState(JsonObj);
272→        }
273→        else if (StateType == TEXT("question"))
274→        {
275→            HandleQuestionState(JsonObj);
276→        }
277→        else if (StateType == TEXT("transition"))
278→        {
279→            HandleTransitionState(JsonObj);
280→        }
281→        else if (StateType == TEXT("finale"))
282→        {
283→            HandleFinaleState(JsonObj);
284→        }
285→        else
286→        {
287→            BridgeLog(FString::Printf(TEXT("Unknown state type: %s"), *StateType));
288→        }
289→    }
290→}
