458→
459→void UBridgeComponent::WriteJsonToFile(const FString& Filename, const TSharedPtr<FJsonObject>& JsonObj)
460→{
461→    FString FilePath = GetBridgeFilePath(Filename);
462→    FString OutputString;
463→
464→    TSharedRef<TJsonWriter<>> Writer = TJsonWriterFactory<>::Create(&OutputString);
465→    FJsonSerializer::Serialize(JsonObj.ToSharedRef(), Writer);
466→
467→    // Write with retry logic (file may be locked by Claude Code reading it)
468→    int32 MaxRetries = 3;
469→    for (int32 Retry = 0; Retry < MaxRetries; ++Retry)
470→    {
471→        if (FFileHelper::SaveStringToFile(OutputString, *FilePath))
472→        {
473→            return; // Success
474→        }
475→
476→        if (Retry < MaxRetries - 1)
477→        {
478→            BridgeLog(FString::Printf(TEXT("Write failed, retry %d/%d..."), Retry + 1, MaxRetries));
479→            FPlatformProcess::Sleep(0.1f);
480→        }
481→    }
482→
483→    BridgeLog(FString::Printf(TEXT("ERROR: Failed to write %s after %d retries"), *Filename, MaxRetries));
484→}
