526→
527→    // Route based on message type
528→    if (MessageType == TEXT("ready"))
529→    {
530→        HandleUsdaReadyState(Content);
531→    }
532→    else if (MessageType == TEXT("question") && SyncStatus == TEXT("question_pending"))
533→    {
534→        HandleUsdaQuestionState(Content);
535→    }
536→    else if (MessageType == TEXT("transition"))
537→    {
538→        HandleUsdaTransitionState(Content);
539→    }
540→    else if (MessageType == TEXT("finale"))
541→    {
542→        HandleUsdaFinaleState(Content);
543→    }
544→
545→    return true;
546→}
